function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function money($v){return number_format((float)$v,0,',',' ').' FG';}
function cleanText($v){return trim(preg_replace('/[|\r\n]+/',' ',(string)$v));}
function nextId(mysqli $conn,string $table):int{
    if(!in_array($table,['produits','mouvements','ventes'],true)) return 1;
    $q=$conn->query("SELECT COALESCE(MAX(id),0)+1 n FROM `$table`");
    return (int)(($q&&$q->fetch_assoc()['n']??1));
}
function parseMeta(string $desc):array{
    $o=[]; foreach(explode('|',$desc) as $p){if(strpos($p,'=')!==false){[$k,$v]=explode('=',$p,2);$o[trim($k)]=trim($v);}} return $o;
}
function invoiceRows(mysqli $conn,string $ref):array{
    $rows=[];$safe=$conn->real_escape_string($ref);
    $q=$conn->query("SELECT m.*,p.nom,p.categorie FROM mouvements m LEFT JOIN produits p ON p.id=m.produit_id WHERE m.type='ENTREE' AND m.description LIKE '%FACTURE=$safe|%' ORDER BY m.id ASC");
    while($q&&($r=$q->fetch_assoc())) $rows[]=$r; return $rows;
}
function flash($t,$m){$_SESSION['flash']=['type'=>$t,'msg'=>$m];}
function purchaseRef(mysqli $conn):string{
    $year=date('Y'); $max=0;
    $q=$conn->query("SELECT description FROM mouvements WHERE type='ENTREE' AND description LIKE 'FACTURE=ACH-$year-%'");
    while($q&&($r=$q->fetch_assoc())){
        if(preg_match('/FACTURE=ACH-'.preg_quote($year,'/').'-(\d{4})\|/',$r['description'],$m)) $max=max($max,(int)$m[1]);
    }
    return 'ACH-'.$year.'-'.str_pad((string)($max+1),4,'0',STR_PAD_LEFT);
}
function qexec(mysqli $conn,string $sql):void{if(!$conn->query($sql)) throw new Exception($conn->error);}

